export type CommunityOnboardingStepType =
  | 'welcome'
  | 'rules'
  | 'single_choice'
  | 'multi_choice'
  | 'channels'
  | 'finish';

export interface CommunityOnboardingOption {
  id: string;
  label: string;
  description?: string;
}

export interface CommunityOnboardingStep {
  id: string;
  type: CommunityOnboardingStepType;
  title: string;
  description: string;
  required: boolean;
  options: CommunityOnboardingOption[];
  channelIds: string[];
}

export interface CommunityOnboardingFlow {
  version: 1;
  enabled: boolean;
  title: string;
  subtitle: string;
  steps: CommunityOnboardingStep[];
  updatedAt?: string;
}

export type CommunityOnboardingAnswer = string | string[] | boolean;
export type CommunityOnboardingAnswers = Record<string, CommunityOnboardingAnswer>;

const MAX_STEPS = 10;
const MAX_OPTIONS = 8;
const STEP_TYPES = new Set<CommunityOnboardingStepType>([
  'welcome',
  'rules',
  'single_choice',
  'multi_choice',
  'channels',
  'finish',
]);

const text = (value: unknown, fallback = '', max = 240) => {
  if (typeof value !== 'string') return fallback;
  const normalized = value.trim().replace(/\s+/g, ' ');
  return normalized ? normalized.slice(0, max) : fallback;
};

const id = (value: unknown, prefix: string) => {
  const existing = text(value, '', 80).replace(/[^a-zA-Z0-9_-]/g, '');
  if (existing) return existing;
  return `${prefix}_${crypto.randomUUID()}`;
};

const normalizeStepType = (value: unknown): CommunityOnboardingStepType => {
  if (value === 'question') return 'single_choice';
  if (value === 'channel_picker') return 'channels';
  return STEP_TYPES.has(value as CommunityOnboardingStepType)
    ? value as CommunityOnboardingStepType
    : 'welcome';
};

const stepDefaults: Record<CommunityOnboardingStepType, Pick<CommunityOnboardingStep, 'title' | 'description' | 'required'>> = {
  welcome: {
    title: 'Welcome aboard',
    description: 'A quick tour will help you find your place in the community.',
    required: false,
  },
  rules: {
    title: 'Make this a great space',
    description: 'Read and accept the community guidelines before continuing.',
    required: true,
  },
  single_choice: {
    title: 'What brings you here?',
    description: 'Choose the answer that fits you best.',
    required: true,
  },
  multi_choice: {
    title: 'What are you interested in?',
    description: 'Pick as many as you like.',
    required: false,
  },
  channels: {
    title: 'Choose your starting spaces',
    description: 'Select the channels you want to explore first.',
    required: false,
  },
  finish: {
    title: "You're all set",
    description: 'Your community is ready. Jump in and say hello.',
    required: false,
  },
};

export const createCommunityOnboardingStep = (type: CommunityOnboardingStepType): CommunityOnboardingStep => ({
  id: `step_${crypto.randomUUID()}`,
  type,
  ...stepDefaults[type],
  options: type === 'single_choice' || type === 'multi_choice'
    ? [
        { id: `option_${crypto.randomUUID()}`, label: 'First option' },
        { id: `option_${crypto.randomUUID()}`, label: 'Second option' },
      ]
    : [],
  channelIds: [],
});

export const createStarterCommunityOnboarding = (communityName = 'your community'): CommunityOnboardingFlow => ({
  version: 1,
  enabled: false,
  title: `Welcome to ${text(communityName, 'your community', 80)}`,
  subtitle: 'Set up your experience in a few quick steps.',
  steps: [
    createCommunityOnboardingStep('welcome'),
    createCommunityOnboardingStep('channels'),
    createCommunityOnboardingStep('finish'),
  ],
});

const normalizeOption = (value: unknown): CommunityOnboardingOption | null => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const record = value as Record<string, unknown>;
  const label = text(record.label, '', 80);
  if (!label) return null;
  const description = text(record.description, '', 180);
  return {
    id: id(record.id, 'option'),
    label,
    ...(description ? { description } : {}),
  };
};

const normalizeStep = (value: unknown): CommunityOnboardingStep | null => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const record = value as Record<string, unknown>;
  const type = normalizeStepType(record.type);
  const defaults = stepDefaults[type];
  const rawChannelIds = Array.isArray(record.channelIds)
    ? record.channelIds
    : Array.isArray(record.channel_ids)
      ? record.channel_ids
      : [];
  const channelIds = Array.from(new Set(rawChannelIds
    .map((channelId) => text(channelId, '', 80))
    .filter(Boolean)))
    .slice(0, 20);
  const options = (Array.isArray(record.options) ? record.options : [])
    .map(normalizeOption)
    .filter((option): option is CommunityOnboardingOption => Boolean(option))
    .slice(0, MAX_OPTIONS);

  return {
    id: id(record.id, 'step'),
    type,
    title: text(record.title, defaults.title, 100),
    description: text(record.description, defaults.description, 320),
    required: type === 'rules' ? true : Boolean(record.required),
    options,
    channelIds,
  };
};

export const normalizeCommunityOnboardingFlow = (
  value: unknown,
  communityName = 'your community',
): CommunityOnboardingFlow => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return createStarterCommunityOnboarding(communityName);
  }
  const record = value as Record<string, unknown>;
  const steps = (Array.isArray(record.steps) ? record.steps : [])
    .map(normalizeStep)
    .filter((step): step is CommunityOnboardingStep => Boolean(step))
    .slice(0, MAX_STEPS);

  if (steps.length === 0) return createStarterCommunityOnboarding(communityName);

  return {
    version: 1,
    enabled: Boolean(record.enabled),
    title: text(record.title, `Welcome to ${text(communityName, 'your community', 80)}`, 100),
    subtitle: text(record.subtitle, 'Set up your experience in a few quick steps.', 220),
    steps,
    ...(typeof record.updatedAt === 'string' ? { updatedAt: record.updatedAt } : {}),
  };
};

export const validateCommunityOnboardingFlow = (flow: CommunityOnboardingFlow) => {
  if (!flow.enabled) return null;
  if (flow.steps.length === 0) return 'Add at least one onboarding step before enabling the flow.';
  const incompleteQuestion = flow.steps.find(
    (step) => (step.type === 'single_choice' || step.type === 'multi_choice') && step.options.length < 2,
  );
  if (incompleteQuestion) return `“${incompleteQuestion.title}” needs at least two answer options.`;
  const emptyChannels = flow.steps.find((step) => step.type === 'channels' && step.channelIds.length === 0);
  if (emptyChannels) return `Choose at least one channel for “${emptyChannels.title}”.`;
  return null;
};

export const isCommunityOnboardingStepComplete = (
  step: CommunityOnboardingStep,
  answer: CommunityOnboardingAnswer | undefined,
) => {
  if (!step.required || step.type === 'welcome' || step.type === 'finish') return true;
  if (step.type === 'rules') return answer === true;
  if (step.type === 'single_choice') return typeof answer === 'string' && answer.length > 0;
  if (step.type === 'multi_choice' || step.type === 'channels') return Array.isArray(answer) && answer.length > 0;
  return true;
};

