import React, { useEffect, useRef } from 'react';
import { ArrowRight, CheckCircle2, Sparkles, Users, X } from 'lucide-react';
import type { CommunityLandingPageConfig } from '@/lib/communityLanding';

interface CommunityLandingExperienceProps {
  community: {
    name: string;
    description?: string | null;
    logo_url?: string | null;
    banner_url?: string | null;
  };
  config: CommunityLandingPageConfig;
  memberCount?: number;
  preview?: boolean;
  joining?: boolean;
  onJoin?: () => void;
  onClose?: () => void;
}

export const CommunityLandingExperience: React.FC<CommunityLandingExperienceProps> = ({
  community,
  config,
  memberCount,
  preview = false,
  joining = false,
  onJoin,
  onClose,
}) => {
  const benefitsRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (preview) return;
    const previousTitle = document.title;
    const description = document.querySelector<HTMLMetaElement>('meta[name="description"]');
    const previousDescription = description?.content;
    document.title = config.seoTitle;
    if (description) description.content = config.seoDescription;
    return () => {
      document.title = previousTitle;
      if (description && previousDescription !== undefined) description.content = previousDescription;
    };
  }, [config.seoDescription, config.seoTitle, preview]);

  return (
    <div className={`${preview ? 'fixed inset-0 z-[85] overflow-y-auto bg-black/85 p-2 backdrop-blur-xl sm:p-6' : 'h-full w-full overflow-y-auto bg-[#f5f5f7]'} text-zinc-950`}>
      <div className={`relative mx-auto min-h-full overflow-hidden bg-[#f5f5f7] ${preview ? 'max-w-6xl rounded-[30px] shadow-2xl sm:rounded-[40px]' : ''}`}>
        <div className="pointer-events-none absolute inset-x-0 top-0 h-[680px] overflow-hidden">
          {community.banner_url ? (
            <img src={community.banner_url} alt="" className="h-full w-full object-cover opacity-[0.13] blur-[2px]" />
          ) : null}
          <div className="absolute inset-0 bg-gradient-to-b from-white/20 via-[#f5f5f7]/85 to-[#f5f5f7]" />
          <div className="absolute -left-32 -top-44 h-[520px] w-[520px] rounded-full opacity-20 blur-3xl" style={{ backgroundColor: config.accentColor }} />
          <div className="absolute -right-40 top-0 h-[440px] w-[440px] rounded-full bg-white blur-3xl" />
        </div>

        <header className="relative z-10 mx-auto flex max-w-6xl items-center justify-between px-5 py-5 sm:px-8 sm:py-7">
          <div className="flex items-center gap-3">
            <div className="grid h-11 w-11 place-items-center overflow-hidden rounded-[15px] bg-zinc-950 text-sm font-bold text-white shadow-lg">
              {community.logo_url ? <img src={community.logo_url} alt="" className="h-full w-full object-cover" /> : community.name.slice(0, 1).toUpperCase()}
            </div>
            <div>
              <p className="text-sm font-semibold tracking-tight">{community.name}</p>
              <p className="text-[11px] text-zinc-400">A Wersee community</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {preview && <span className="hidden rounded-full bg-amber-100 px-3 py-1.5 text-xs font-semibold text-amber-800 sm:inline">Draft preview</span>}
            {onClose ? (
              <button type="button" onClick={onClose} className="grid h-11 w-11 place-items-center rounded-full bg-white/75 text-zinc-500 shadow-sm backdrop-blur-xl transition hover:bg-white hover:text-black" aria-label="Close landing page preview"><X className="h-4 w-4" /></button>
            ) : (
              <button type="button" onClick={onJoin} disabled={joining} className="min-h-11 rounded-full bg-zinc-950 px-5 text-sm font-semibold text-white shadow-lg transition hover:bg-black disabled:opacity-50">{joining ? 'Joining…' : config.primaryCta}</button>
            )}
          </div>
        </header>

        <main className="relative z-[1]">
          <section className="mx-auto flex min-h-[560px] max-w-5xl flex-col items-center justify-center px-5 pb-24 pt-14 text-center sm:px-8 sm:pt-20">
            <div className="inline-flex items-center gap-2 rounded-full border border-black/[0.06] bg-white/65 px-4 py-2 text-[11px] font-semibold uppercase tracking-[0.16em] text-zinc-600 shadow-sm backdrop-blur-xl">
              <Sparkles className="h-3.5 w-3.5" style={{ color: config.accentColor }} />
              {config.eyebrow}
            </div>
            <h1 className="mt-8 max-w-4xl text-balance text-5xl font-semibold leading-[0.98] tracking-[-0.055em] text-zinc-950 sm:text-7xl lg:text-[88px]">{config.headline}</h1>
            <p className="mt-7 max-w-2xl text-balance text-base leading-7 text-zinc-500 sm:text-xl sm:leading-8">{config.subheadline}</p>
            <div className="mt-9 flex w-full flex-col items-center justify-center gap-3 sm:w-auto sm:flex-row">
              <button
                type="button"
                onClick={onJoin}
                disabled={joining || !onJoin}
                className="inline-flex min-h-14 w-full items-center justify-center gap-2 rounded-full bg-zinc-950 px-7 text-sm font-semibold text-white shadow-xl shadow-black/15 transition hover:-translate-y-0.5 hover:bg-black disabled:transform-none disabled:opacity-50 sm:w-auto"
              >
                {joining ? 'Joining…' : config.primaryCta}<ArrowRight className="h-4 w-4" />
              </button>
              <button
                type="button"
                onClick={() => benefitsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' })}
                className="min-h-14 w-full rounded-full border border-black/[0.08] bg-white/70 px-7 text-sm font-semibold text-zinc-700 shadow-sm backdrop-blur-xl transition hover:bg-white sm:w-auto"
              >
                {config.secondaryCta}
              </button>
            </div>
            {typeof memberCount === 'number' && memberCount > 0 && (
              <p className="mt-7 inline-flex items-center gap-2 text-xs font-medium text-zinc-400"><Users className="h-3.5 w-3.5" /> Join {memberCount.toLocaleString()} member{memberCount === 1 ? '' : 's'}</p>
            )}
          </section>

          <section ref={benefitsRef} className="mx-auto max-w-6xl px-5 pb-24 sm:px-8 sm:pb-32">
            <div className="grid overflow-hidden rounded-[30px] border border-black/[0.06] bg-white shadow-sm sm:rounded-[40px] md:grid-cols-3">
              {config.benefits.slice(0, 3).map((benefit, index) => (
                <article key={`${benefit.title}-${index}`} className={`p-7 sm:p-9 ${index > 0 ? 'border-t border-black/[0.06] md:border-l md:border-t-0' : ''}`}>
                  <div className="grid h-11 w-11 place-items-center rounded-2xl bg-zinc-100">
                    <CheckCircle2 className="h-5 w-5" style={{ color: config.accentColor }} />
                  </div>
                  <h2 className="mt-7 text-xl font-semibold tracking-tight text-zinc-950">{benefit.title}</h2>
                  <p className="mt-2 text-sm leading-6 text-zinc-500">{benefit.description}</p>
                </article>
              ))}
            </div>

            <div className="mt-5 overflow-hidden rounded-[30px] bg-zinc-950 px-7 py-10 text-white sm:rounded-[40px] sm:px-12 sm:py-14">
              <div className="flex flex-col items-start justify-between gap-8 sm:flex-row sm:items-center">
                <div>
                  <p className="text-xs font-semibold uppercase tracking-[0.18em] text-white/35">Ready when you are</p>
                  <h2 className="mt-3 max-w-2xl text-3xl font-semibold tracking-[-0.035em] sm:text-4xl">A thoughtful space for the conversations that matter.</h2>
                </div>
                <button type="button" onClick={onJoin} disabled={joining || !onJoin} className="inline-flex min-h-14 shrink-0 items-center gap-2 rounded-full bg-white px-7 text-sm font-semibold text-black transition hover:bg-zinc-200 disabled:opacity-50">{config.primaryCta}<ArrowRight className="h-4 w-4" /></button>
              </div>
            </div>
          </section>
        </main>
      </div>
    </div>
  );
};

