import React, { useState, useRef, useEffect } from 'react';
import { Plus, ArrowUp, X, FileText, Mic, Smile, Image as ImageIcon, AtSign, Users as UsersIcon, Loader2 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

interface ChatInputProps {
  onSendMessage: (
    content: string,
    attachments?: any[],
    onUploadProgress?: (progress: UploadProgress) => void,
  ) => Promise<boolean | void> | boolean | void;
  channelName: string;
  onFileTooLarge: (limitBytes: number) => void;
  onStartRecording?: () => void;
  members?: any[];
  roles?: any[];
  onTypingChange?: (isTyping: boolean) => void;
  placeholder?: string;
  maxFileSizeBytes?: number;
  maxVideoFileSizeBytes?: number;
  placement?: 'floating' | 'panel';
  submitLabel?: string;
}

type UploadProgress = {
  percent: number;
  transferredBytes: number;
  totalBytes: number;
};

const formatUploadBytes = (bytes: number) => {
  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  const unitIndex = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
  const value = bytes / (1024 ** unitIndex);
  return `${value >= 10 || unitIndex === 0 ? value.toFixed(0) : value.toFixed(1)} ${units[unitIndex]}`;
};

const DEFAULT_MAX_FILE_SIZE_BYTES = 512 * 1024 * 1024;

export const ChatInput: React.FC<ChatInputProps> = ({ 
  onSendMessage, 
  channelName, 
  onFileTooLarge, 
  onStartRecording,
  members = [],
  roles = [],
  onTypingChange,
  placeholder,
  maxFileSizeBytes = DEFAULT_MAX_FILE_SIZE_BYTES,
  maxVideoFileSizeBytes,
  placement = 'floating',
  submitLabel = 'Send message',
}) => {
  const [message, setMessage] = useState('');
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [showPlusMenu, setShowPlusMenu] = useState(false);
  const [showMentions, setShowMentions] = useState(false);
  const [showEmoji, setShowEmoji] = useState(false);
  const [mentionFilter, setMentionFilter] = useState('');
  const [mentionIndex, setMentionIndex] = useState(0);
  const [isSending, setIsSending] = useState(false);
  const [uploadProgress, setUploadProgress] = useState<UploadProgress | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const filteredMentions = [
    { id: 'everyone', name: 'everyone', type: 'special' },
    ...roles.map(r => ({ id: r.id, name: r.name, type: 'role' })),
    ...members.map(m => ({ id: m.user_id, name: m.user?.full_name || m.full_name || 'Unknown', type: 'user' }))
  ].filter(m => m.name.toLowerCase().includes(mentionFilter.toLowerCase()));

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (showPlusMenu || showMentions || showEmoji) {
        setShowPlusMenu(false);
        setShowMentions(false);
        setShowEmoji(false);
      }
    };
    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, [showEmoji, showPlusMenu, showMentions]);

  useEffect(() => () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
  }, [previewUrl]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setMessage(val);
    onTypingChange?.(val.trim().length > 0);

    const lastAtPos = val.lastIndexOf('@');
    if (lastAtPos !== -1 && (lastAtPos === 0 || val[lastAtPos - 1] === ' ')) {
      const filter = val.slice(lastAtPos + 1);
      if (!filter.includes(' ')) {
        setMentionFilter(filter);
        setShowMentions(true);
        setMentionIndex(0);
        return;
      }
    }
    setShowMentions(false);
  };

  const insertMention = (mention: any) => {
    const lastAtPos = message.lastIndexOf('@');
    const before = message.slice(0, lastAtPos);
    const after = message.slice(lastAtPos + mentionFilter.length + 1);
    const token = mention.type === 'special' ? `@${mention.name}` : `<@${mention.id}>`;
    setMessage(`${before}${token} ${after}`);
    setShowMentions(false);
    inputRef.current?.focus();
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (showMentions) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setMentionIndex(prev => (prev + 1) % filteredMentions.length);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setMentionIndex(prev => (prev - 1 + filteredMentions.length) % filteredMentions.length);
      } else if (e.key === 'Enter' || e.key === 'Tab') {
        e.preventDefault();
        if (filteredMentions[mentionIndex]) {
          insertMention(filteredMentions[mentionIndex]);
        }
      } else if (e.key === 'Escape') {
        setShowMentions(false);
      }
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const fileSizeLimit = file.type.startsWith('video/') && maxVideoFileSizeBytes
      ? maxVideoFileSizeBytes
      : maxFileSizeBytes;
    if (file.size > fileSizeLimit) {
      onFileTooLarge(fileSizeLimit);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setSelectedFile(file);
    
    // Create preview for images/videos
    if (file.type.startsWith('image/') || file.type.startsWith('video/')) {
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);
    }
  };

  const removeFile = () => {
    setSelectedFile(null);
    if (previewUrl) {
      URL.revokeObjectURL(previewUrl);
      setPreviewUrl(null);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!message.trim() && !selectedFile) || isSending) return;

    const attachments = selectedFile ? [{ file: selectedFile, type: selectedFile.type }] : undefined;

    setIsSending(true);
    setUploadProgress(null);
    try {
      const sent = await onSendMessage(message, attachments, setUploadProgress);
      if (sent === false) return;
      onTypingChange?.(false);
      setMessage('');
      removeFile();
    } finally {
      setIsSending(false);
      setUploadProgress(null);
    }
  };

  return (
    <div className={`pointer-events-none z-30 shrink-0 ${placement === 'panel'
      ? 'border-t border-white/[0.06] bg-[#0d0d0f]/96 px-3 pb-[max(10px,env(safe-area-inset-bottom))] pt-3 sm:px-4 sm:pb-4'
      : 'bg-gradient-to-t from-[#080809] via-[#080809]/95 to-transparent px-3 pb-[max(10px,env(safe-area-inset-bottom))] pt-6 sm:px-5 sm:pb-4'
    }`}>
      <div className={`pointer-events-auto relative mx-auto ${placement === 'panel' ? 'max-w-none' : 'max-w-5xl'}`}>
        
        {/* Mentions Dropdown */}
        <AnimatePresence>
          {showMentions && filteredMentions.length > 0 && (
            <motion.div
              initial={{ opacity: 0, y: 10, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 10, scale: 0.95 }}
              className="absolute bottom-full left-0 z-50 mb-3 w-64 overflow-hidden rounded-[24px] border border-white/[0.1] bg-[#111113]/95 shadow-[0_24px_65px_rgba(0,0,0,0.55)] backdrop-blur-3xl"
            >
              <div className="p-2 max-h-64 overflow-y-auto">
                {filteredMentions.map((mention, i) => (
                  <button
                    key={mention.id}
                    onClick={() => insertMention(mention)}
                    onMouseEnter={() => setMentionIndex(i)}
                    className={`w-full flex items-center gap-3 px-3 py-2 rounded-xl transition-colors ${
                      i === mentionIndex ? 'bg-indigo-600 text-white' : 'text-gray-400 hover:bg-white/5'
                    }`}
                  >
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${
                      mention.type === 'role' ? 'bg-amber-500/20 text-amber-400' : 
                      mention.type === 'special' ? 'bg-indigo-500/20 text-indigo-400' :
                      'bg-white/10 text-white'
                    }`}>
                      {mention.type === 'role' ? <UsersIcon className="w-4 h-4" /> : 
                       mention.type === 'special' ? <AtSign className="w-4 h-4" /> :
                       <AtSign className="w-4 h-4" />}
                    </div>
                    <div className="flex flex-col items-start min-w-0">
                      <span className="text-sm font-bold truncate">{mention.name}</span>
                      <span className="text-[10px] opacity-60 uppercase tracking-wider font-bold">
                        {mention.type}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Plus Menu Dropdown */}
        <AnimatePresence>
          {showPlusMenu && (
            <motion.div
              initial={{ opacity: 0, y: 10, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 10, scale: 0.95 }}
              className="absolute bottom-full left-0 z-50 mb-3 w-56 overflow-hidden rounded-[24px] border border-white/[0.1] bg-[#111113]/95 shadow-[0_24px_65px_rgba(0,0,0,0.55)] backdrop-blur-3xl"
            >
              <div className="p-2 space-y-1">
                <button
                  onClick={() => {
                    fileInputRef.current?.click();
                    setShowPlusMenu(false);
                  }}
                  className="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-gray-400 hover:text-white hover:bg-white/5 transition-all group"
                >
                  <div className="w-8 h-8 rounded-lg bg-emerald-500/20 flex items-center justify-center group-hover:scale-110 transition-transform">
                    <ImageIcon className="w-4 h-4 text-emerald-400" />
                  </div>
                  <span className="text-sm font-bold">Upload photo or video</span>
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <AnimatePresence>
          {showEmoji && (
            <motion.div
              initial={{ opacity: 0, y: 10, scale: 0.96 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 10, scale: 0.96 }}
              className="absolute bottom-full right-0 z-50 mb-3 flex gap-1 rounded-[22px] border border-white/[0.1] bg-[#111113]/95 p-2 shadow-[0_24px_65px_rgba(0,0,0,0.55)] backdrop-blur-3xl"
            >
              {['😀', '😂', '❤️', '🔥', '👏', '🎉', '👍', '👀'].map((emoji) => (
                <button
                  key={emoji}
                  type="button"
                  onClick={() => {
                    setMessage((current) => `${current}${emoji}`);
                    onTypingChange?.(true);
                    setShowEmoji(false);
                    inputRef.current?.focus();
                  }}
                  className="grid h-10 w-10 place-items-center rounded-xl text-xl transition hover:bg-white/10"
                  aria-label={`Add ${emoji}`}
                >
                  {emoji}
                </button>
              ))}
            </motion.div>
          )}
        </AnimatePresence>

        {/* Attachment Preview */}
        <AnimatePresence>
          {selectedFile && previewUrl && (
            <motion.div 
              initial={{ opacity: 0, y: 20, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 20, scale: 0.95 }}
              className="absolute bottom-full left-0 mb-3 flex items-center gap-4 rounded-[22px] border border-white/[0.1] bg-[#111113]/95 p-3 shadow-[0_24px_65px_rgba(0,0,0,0.55)] backdrop-blur-3xl"
            >
              <div className="relative w-16 h-16 rounded-xl overflow-hidden bg-black/50 border border-white/5">
                {selectedFile.type.startsWith('image/') ? (
                  <img src={previewUrl} alt="Preview" className="w-full h-full object-cover" />
                ) : selectedFile.type.startsWith('video/') ? (
                  <video src={previewUrl} className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <FileText className="w-8 h-8 text-white/50" />
                  </div>
                )}
                <button 
                  type="button"
                  onClick={removeFile}
                  className="absolute top-1 right-1 p-1 bg-black/50 hover:bg-black/80 rounded-full text-white transition-colors backdrop-blur-sm"
                >
                  <X className="w-3 h-3" />
                </button>
              </div>
              <div className="flex flex-col min-w-0 pr-4">
                <div className="text-sm font-bold text-white truncate max-w-[160px]">
                  {selectedFile.name}
                </div>
                <div className="text-[10px] text-gray-500 font-medium">
                  {(selectedFile.size / (1024 * 1024)).toFixed(2)} MB
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {uploadProgress && (
          <div className="mb-2 ml-14 flex items-center gap-2 rounded-full border border-white/[0.1] bg-[#141416]/92 px-3 py-2 text-[11px] font-semibold text-white/55 shadow-[0_12px_32px_rgba(0,0,0,0.32)] backdrop-blur-2xl">
            <span className="h-1.5 flex-1 overflow-hidden rounded-full bg-white/[0.08]">
              <span
                className="block h-full rounded-full bg-white transition-[width] duration-200"
                style={{ width: `${Math.min(100, Math.max(0, uploadProgress.percent))}%` }}
              />
            </span>
            <span className="shrink-0 tabular-nums">{formatUploadBytes(uploadProgress.transferredBytes)} / {formatUploadBytes(uploadProgress.totalBytes)} · {uploadProgress.percent}%</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex items-end gap-2">
          <input 
            type="file" 
            ref={fileInputRef}
            onChange={handleFileSelect}
            className="hidden"
            accept="image/*,video/*"
            disabled={isSending}
          />
          
          <motion.button
            type="button"
            whileTap={{ scale: 0.9 }}
            disabled={isSending}
            onClick={(event) => {
              event.stopPropagation();
              setShowPlusMenu((open) => !open);
              setShowEmoji(false);
            }}
            className={`grid h-12 w-12 shrink-0 place-items-center rounded-full border shadow-[0_12px_35px_rgba(0,0,0,0.35)] backdrop-blur-2xl transition disabled:cursor-not-allowed disabled:opacity-45 ${showPlusMenu ? 'border-white/20 bg-white text-black' : 'border-white/[0.11] bg-[#141416]/90 text-white hover:bg-[#1b1b1e]'}`}
            title="Attach file"
            aria-label="Attach file"
            aria-haspopup="menu"
            aria-expanded={showPlusMenu}
          >
            <Plus className={`h-5 w-5 transition-transform duration-300 ${showPlusMenu ? 'rotate-45' : ''}`} />
          </motion.button>

          <div className="min-w-0 flex-1 rounded-[25px] border border-white/[0.11] bg-[#141416]/92 p-1.5 shadow-[0_18px_50px_rgba(0,0,0,0.4)] backdrop-blur-3xl transition-all focus-within:border-white/20">
            <div className="flex min-h-9 items-center gap-1 pl-3.5">
              <input
                ref={inputRef}
                data-mobile-keyboard-target="chat"
                type="text"
                value={message}
                onChange={handleInputChange}
                onKeyDown={handleKeyDown}
                onBlur={() => onTypingChange?.(false)}
                placeholder={placeholder || `Message #${channelName}`}
                disabled={isSending}
                className="min-h-6 min-w-0 flex-1 border-0 bg-transparent py-2 text-[15px] leading-6 text-white outline-none placeholder:text-white/28 focus:outline-none focus-visible:outline-none"
              />

              <div className="flex shrink-0 items-center gap-0.5">
                <button 
                  type="button"
                  onClick={(event) => {
                    event.stopPropagation();
                    setShowEmoji((current) => !current);
                    setShowPlusMenu(false);
                  }}
                  className={`hidden h-9 w-9 place-items-center rounded-full text-white/35 transition hover:bg-white/[0.07] hover:text-white sm:grid ${showEmoji ? 'bg-white/[0.08] text-white' : ''}`}
                  title="Emoji"
                  aria-label="Add emoji"
                  aria-expanded={showEmoji}
                >
                  <Smile className="h-4 w-4" />
                </button>
                
                {onStartRecording && (
                  <button 
                    type="button"
                    onClick={onStartRecording}
                    disabled={isSending}
                    className="grid h-9 w-9 place-items-center rounded-full text-white/35 transition hover:bg-white/[0.07] hover:text-white"
                    title="Voice Message"
                    aria-label="Record a voice message"
                  >
                    <Mic className="h-4 w-4" />
                  </button>
                )}

                <motion.button
                  type="submit"
                  whileTap={{ scale: 0.9 }}
                  disabled={isSending || (!message.trim() && !selectedFile)}
                  className={`grid h-9 w-9 shrink-0 place-items-center rounded-full transition ${
                    !isSending && (message.trim() || selectedFile)
                      ? 'bg-white text-black hover:bg-zinc-200'
                      : 'cursor-not-allowed bg-white/[0.08] text-white/25'
                  }`}
                  aria-label={submitLabel}
                >
                  {isSending ? <Loader2 className="h-4 w-4 animate-spin" /> : <ArrowUp className="h-4 w-4" strokeWidth={2.4} />}
                </motion.button>
              </div>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};
