export type CallTransportChannel = {
  chatId?: string | null;
  communityId?: string | null;
  community_id?: string | null;
};

export type CallTransport = {
  realtimeTopic: string;
  usesChatLifecycle: boolean;
};

const cleanId = (value?: string | null) => value?.trim() || null;

export const resolveCallTransport = (channel: CallTransportChannel): CallTransport => {
  const chatId = cleanId(channel.chatId);
  if (chatId) {
    return {
      realtimeTopic: `chat:${chatId}`,
      usesChatLifecycle: true,
    };
  }

  const communityId = cleanId(channel.communityId) || cleanId(channel.community_id);
  if (communityId) {
    return {
      realtimeTopic: `community:${communityId}`,
      usesChatLifecycle: false,
    };
  }

  throw new Error('Call room is not configured.');
};
