import React, { useEffect, useMemo, useState } from 'react';
import {
  ArrowDown,
  ArrowUp,
  Check,
  CheckCircle2,
  ChevronRight,
  CircleHelp,
  Flag,
  Hash,
  ListChecks,
  Plus,
  ShieldCheck,
  Sparkles,
  Trash2,
  Users,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import {
  createCommunityOnboardingStep,
  type CommunityOnboardingFlow,
  type CommunityOnboardingStep,
  type CommunityOnboardingStepType,
} from '@/lib/communityOnboarding';

interface CommunityChannel {
  id: string;
  name: string;
  type?: string | null;
}

interface CommunityOnboardingBuilderProps {
  value: CommunityOnboardingFlow;
  channels: CommunityChannel[];
  saving: boolean;
  onChange: (value: CommunityOnboardingFlow) => void;
  onSave: () => void;
}

const STEP_CATALOG: Array<{
  type: CommunityOnboardingStepType;
  label: string;
  description: string;
  icon: LucideIcon;
}> = [
  { type: 'welcome', label: 'Welcome', description: 'Set the tone', icon: Sparkles },
  { type: 'rules', label: 'Guidelines', description: 'Ask for agreement', icon: ShieldCheck },
  { type: 'single_choice', label: 'One choice', description: 'Learn one preference', icon: CircleHelp },
  { type: 'multi_choice', label: 'Multiple choice', description: 'Collect interests', icon: ListChecks },
  { type: 'channels', label: 'Channel picks', description: 'Guide discovery', icon: Hash },
  { type: 'finish', label: 'Finish', description: 'Open the community', icon: Flag },
];

const inputClass = 'w-full rounded-2xl border border-black/[0.08] bg-white px-4 py-3 text-sm text-zinc-900 outline-none transition placeholder:text-zinc-400 focus:border-indigo-400 focus:ring-4 focus:ring-indigo-500/10';

const stepLabel = (type: CommunityOnboardingStepType) => STEP_CATALOG.find((item) => item.type === type)?.label || 'Step';

const updateStep = (
  flow: CommunityOnboardingFlow,
  stepId: string,
  updater: (step: CommunityOnboardingStep) => CommunityOnboardingStep,
): CommunityOnboardingFlow => ({
  ...flow,
  steps: flow.steps.map((step) => step.id === stepId ? updater(step) : step),
});

export const CommunityOnboardingBuilder: React.FC<CommunityOnboardingBuilderProps> = ({
  value,
  channels,
  saving,
  onChange,
  onSave,
}) => {
  const [selectedStepId, setSelectedStepId] = useState(value.steps[0]?.id || '');
  const [showStepCatalog, setShowStepCatalog] = useState(false);
  const selectedStep = useMemo(
    () => value.steps.find((step) => step.id === selectedStepId) || value.steps[0] || null,
    [selectedStepId, value.steps],
  );

  useEffect(() => {
    if (selectedStep || value.steps.length === 0) return;
    setSelectedStepId(value.steps[0].id);
  }, [selectedStep, value.steps]);

  const patchSelectedStep = (patch: Partial<CommunityOnboardingStep>) => {
    if (!selectedStep) return;
    onChange(updateStep(value, selectedStep.id, (step) => ({ ...step, ...patch })));
  };

  const addStep = (type: CommunityOnboardingStepType) => {
    const newStep = createCommunityOnboardingStep(type);
    onChange({ ...value, steps: [...value.steps, newStep] });
    setSelectedStepId(newStep.id);
    setShowStepCatalog(false);
  };

  const moveStep = (direction: -1 | 1) => {
    if (!selectedStep) return;
    const index = value.steps.findIndex((step) => step.id === selectedStep.id);
    const target = index + direction;
    if (index < 0 || target < 0 || target >= value.steps.length) return;
    const steps = [...value.steps];
    [steps[index], steps[target]] = [steps[target], steps[index]];
    onChange({ ...value, steps });
  };

  const removeSelectedStep = () => {
    if (!selectedStep) return;
    const index = value.steps.findIndex((step) => step.id === selectedStep.id);
    const steps = value.steps.filter((step) => step.id !== selectedStep.id);
    onChange({ ...value, steps });
    setSelectedStepId(steps[Math.min(index, Math.max(0, steps.length - 1))]?.id || '');
  };

  const selectedIndex = selectedStep ? value.steps.findIndex((step) => step.id === selectedStep.id) : -1;

  return (
    <div className="overflow-hidden rounded-[28px] border border-white/10 bg-[#08080a] shadow-2xl shadow-black/30">
      <div className="border-b border-white/10 bg-gradient-to-r from-white/[0.07] to-white/[0.02] px-5 py-5 sm:px-7">
        <div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <div className="mb-2 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[0.18em] text-indigo-300">
              <Sparkles className="h-3.5 w-3.5" aria-hidden="true" />
              Wersee onboarding
            </div>
            <h2 className="text-2xl font-semibold tracking-tight text-white">Design the first five minutes.</h2>
            <p className="mt-1.5 max-w-xl text-sm leading-6 text-white/45">Welcome people, set expectations and guide them to the right conversations.</p>
          </div>
          <div className="flex items-center gap-3">
            <label className="flex min-h-11 cursor-pointer items-center gap-3 rounded-full border border-white/10 bg-white/[0.05] px-4 text-sm font-medium text-white/70">
              <input
                type="checkbox"
                checked={value.enabled}
                onChange={(event) => onChange({ ...value, enabled: event.target.checked })}
                className="peer sr-only"
              />
              <span className="relative h-6 w-10 rounded-full bg-white/15 transition peer-checked:bg-indigo-500 peer-focus-visible:ring-2 peer-focus-visible:ring-indigo-300">
                <span className={`absolute top-1 h-4 w-4 rounded-full bg-white shadow transition-transform ${value.enabled ? 'translate-x-5' : 'translate-x-1'}`} />
              </span>
              {value.enabled ? 'Live after save' : 'Draft'}
            </label>
            <button
              type="button"
              onClick={onSave}
              disabled={saving}
              className="inline-flex min-h-11 items-center justify-center gap-2 rounded-full bg-white px-5 text-sm font-semibold text-black transition hover:bg-zinc-200 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {saving ? <span className="h-4 w-4 animate-spin rounded-full border-2 border-black/20 border-t-black" /> : <Check className="h-4 w-4" aria-hidden="true" />}
              Save flow
            </button>
          </div>
        </div>
      </div>

      <div className="grid min-h-[660px] md:grid-cols-[220px_minmax(0,1fr)] xl:grid-cols-[250px_minmax(0,1fr)_300px]">
        <aside className="border-b border-white/10 p-4 md:border-b-0 md:border-r">
          <div className="mb-3 flex items-center justify-between px-2">
            <span className="text-[11px] font-bold uppercase tracking-[0.16em] text-white/35">Steps</span>
            <span className="text-xs text-white/25">{value.steps.length}/10</span>
          </div>
          <div className="space-y-1.5">
            {value.steps.map((step, index) => {
              const catalogItem = STEP_CATALOG.find((item) => item.type === step.type);
              const Icon = catalogItem?.icon || Sparkles;
              const selected = selectedStep?.id === step.id;
              return (
                <button
                  key={step.id}
                  type="button"
                  onClick={() => setSelectedStepId(step.id)}
                  className={`flex min-h-14 w-full items-center gap-3 rounded-2xl px-3 text-left transition ${selected ? 'bg-white text-black shadow-lg' : 'text-white/55 hover:bg-white/[0.06] hover:text-white'}`}
                  aria-current={selected ? 'step' : undefined}
                >
                  <span className={`grid h-8 w-8 shrink-0 place-items-center rounded-xl ${selected ? 'bg-black/[0.06]' : 'bg-white/[0.06]'}`}>
                    <Icon className="h-4 w-4" aria-hidden="true" />
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block text-[10px] font-bold uppercase tracking-wider opacity-45">{index + 1}. {stepLabel(step.type)}</span>
                    <span className="block truncate text-sm font-semibold">{step.title}</span>
                  </span>
                  <ChevronRight className="h-4 w-4 opacity-35" aria-hidden="true" />
                </button>
              );
            })}
          </div>

          <div className="relative mt-3">
            <button
              type="button"
              onClick={() => setShowStepCatalog((open) => !open)}
              disabled={value.steps.length >= 10}
              className="flex min-h-12 w-full items-center justify-center gap-2 rounded-2xl border border-dashed border-white/15 text-sm font-semibold text-white/55 transition hover:border-white/30 hover:bg-white/[0.04] hover:text-white disabled:opacity-40"
              aria-expanded={showStepCatalog}
            >
              <Plus className="h-4 w-4" aria-hidden="true" />
              Add step
            </button>
            {showStepCatalog && (
              <div className="absolute left-0 top-14 z-20 grid w-[min(500px,calc(100vw-3rem))] grid-cols-2 gap-2 rounded-3xl border border-white/10 bg-[#17171a] p-3 shadow-2xl sm:grid-cols-3 lg:w-[510px]">
                {STEP_CATALOG.map((item) => (
                  <button
                    key={item.type}
                    type="button"
                    onClick={() => addStep(item.type)}
                    className="rounded-2xl p-3 text-left transition hover:bg-white/[0.07]"
                  >
                    <item.icon className="mb-3 h-5 w-5 text-indigo-300" aria-hidden="true" />
                    <span className="block text-sm font-semibold text-white">{item.label}</span>
                    <span className="mt-0.5 block text-xs text-white/35">{item.description}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </aside>

        <section className="bg-[#f5f5f7] p-5 text-zinc-900 sm:p-7">
          <div className="mb-7 grid gap-4 sm:grid-cols-2">
            <div>
              <label className="mb-2 block text-xs font-semibold text-zinc-500">Flow title</label>
              <input
                value={value.title}
                maxLength={100}
                onChange={(event) => onChange({ ...value, title: event.target.value })}
                className={inputClass}
              />
            </div>
            <div>
              <label className="mb-2 block text-xs font-semibold text-zinc-500">Short introduction</label>
              <input
                value={value.subtitle}
                maxLength={220}
                onChange={(event) => onChange({ ...value, subtitle: event.target.value })}
                className={inputClass}
              />
            </div>
          </div>

          {selectedStep ? (
            <div className="rounded-[26px] border border-black/[0.07] bg-white p-5 shadow-sm sm:p-6">
              <div className="mb-6 flex items-start justify-between gap-4 border-b border-black/[0.06] pb-5">
                <div>
                  <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-indigo-500">Step {selectedIndex + 1} · {stepLabel(selectedStep.type)}</p>
                  <h3 className="mt-1 text-xl font-semibold tracking-tight">Edit this moment</h3>
                </div>
                <div className="flex gap-1">
                  <button type="button" onClick={() => moveStep(-1)} disabled={selectedIndex <= 0} className="rounded-full p-2 text-zinc-500 hover:bg-zinc-100 disabled:opacity-25" aria-label="Move step up"><ArrowUp className="h-4 w-4" /></button>
                  <button type="button" onClick={() => moveStep(1)} disabled={selectedIndex === value.steps.length - 1} className="rounded-full p-2 text-zinc-500 hover:bg-zinc-100 disabled:opacity-25" aria-label="Move step down"><ArrowDown className="h-4 w-4" /></button>
                  <button type="button" onClick={removeSelectedStep} className="rounded-full p-2 text-zinc-400 hover:bg-red-50 hover:text-red-500" aria-label="Delete step"><Trash2 className="h-4 w-4" /></button>
                </div>
              </div>

              <div className="space-y-5">
                <div>
                  <label className="mb-2 block text-xs font-semibold text-zinc-500">Title</label>
                  <input value={selectedStep.title} maxLength={100} onChange={(event) => patchSelectedStep({ title: event.target.value })} className={inputClass} />
                </div>
                <div>
                  <label className="mb-2 block text-xs font-semibold text-zinc-500">Description</label>
                  <textarea value={selectedStep.description} maxLength={320} onChange={(event) => patchSelectedStep({ description: event.target.value })} className={`${inputClass} min-h-24 resize-y`} />
                </div>

                {(selectedStep.type === 'single_choice' || selectedStep.type === 'multi_choice') && (
                  <div>
                    <div className="mb-2 flex items-center justify-between">
                      <label className="text-xs font-semibold text-zinc-500">Answer options</label>
                      <button
                        type="button"
                        onClick={() => patchSelectedStep({ options: [...selectedStep.options, { id: `option_${crypto.randomUUID()}`, label: `Option ${selectedStep.options.length + 1}` }] })}
                        disabled={selectedStep.options.length >= 8}
                        className="text-xs font-semibold text-indigo-600 hover:text-indigo-500 disabled:opacity-40"
                      >
                        + Add option
                      </button>
                    </div>
                    <div className="space-y-2">
                      {selectedStep.options.map((option, optionIndex) => (
                        <div key={option.id} className="flex items-center gap-2">
                          <span className={`h-4 w-4 shrink-0 ${selectedStep.type === 'single_choice' ? 'rounded-full border-2 border-zinc-300' : 'rounded border border-zinc-300'}`} />
                          <input
                            value={option.label}
                            maxLength={80}
                            onChange={(event) => patchSelectedStep({ options: selectedStep.options.map((item) => item.id === option.id ? { ...item, label: event.target.value } : item) })}
                            className={`${inputClass} py-2.5`}
                          />
                          <button
                            type="button"
                            onClick={() => patchSelectedStep({ options: selectedStep.options.filter((item) => item.id !== option.id) })}
                            className="rounded-full p-2 text-zinc-300 hover:bg-red-50 hover:text-red-500"
                            aria-label={`Delete option ${optionIndex + 1}`}
                          >
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {selectedStep.type === 'channels' && (
                  <fieldset>
                    <legend className="mb-2 text-xs font-semibold text-zinc-500">Channels to recommend</legend>
                    <div className="grid gap-2 sm:grid-cols-2">
                      {channels.filter((channel) => channel.type !== 'voice' && channel.type !== 'video').map((channel) => {
                        const checked = selectedStep.channelIds.includes(channel.id);
                        return (
                          <label key={channel.id} className={`flex min-h-12 cursor-pointer items-center gap-3 rounded-2xl border px-3 text-sm font-medium transition ${checked ? 'border-indigo-200 bg-indigo-50 text-indigo-900' : 'border-black/[0.07] bg-zinc-50 text-zinc-600 hover:bg-zinc-100'}`}>
                            <input
                              type="checkbox"
                              checked={checked}
                              onChange={() => patchSelectedStep({
                                channelIds: checked
                                  ? selectedStep.channelIds.filter((id) => id !== channel.id)
                                  : [...selectedStep.channelIds, channel.id],
                              })}
                              className="sr-only"
                            />
                            <Hash className="h-4 w-4" aria-hidden="true" />
                            <span className="min-w-0 flex-1 truncate">{channel.name}</span>
                            {checked && <CheckCircle2 className="h-4 w-4 text-indigo-500" aria-hidden="true" />}
                          </label>
                        );
                      })}
                      {channels.length === 0 && <p className="text-sm text-zinc-400">Create a channel before adding channel recommendations.</p>}
                    </div>
                  </fieldset>
                )}

                {!['welcome', 'finish', 'rules'].includes(selectedStep.type) && (
                  <label className="flex cursor-pointer items-center justify-between rounded-2xl bg-zinc-50 px-4 py-3">
                    <span>
                      <span className="block text-sm font-semibold text-zinc-800">Required answer</span>
                      <span className="block text-xs text-zinc-400">Members must respond to continue.</span>
                    </span>
                    <input type="checkbox" checked={selectedStep.required} onChange={(event) => patchSelectedStep({ required: event.target.checked })} className="h-5 w-5 accent-indigo-600" />
                  </label>
                )}
              </div>
            </div>
          ) : (
            <div className="grid min-h-80 place-items-center rounded-[26px] border border-dashed border-black/10 bg-white/50 text-center">
              <div><Users className="mx-auto h-8 w-8 text-zinc-300" /><p className="mt-3 text-sm text-zinc-500">Add a step to begin.</p></div>
            </div>
          )}
        </section>

        <aside className="border-t border-white/10 bg-[#111114] p-5 md:col-span-2 xl:col-span-1 xl:border-l xl:border-t-0">
          <div className="mb-4 flex items-center justify-between">
            <span className="text-[11px] font-bold uppercase tracking-[0.16em] text-white/35">Member preview</span>
            <span className="rounded-full bg-white/[0.06] px-2.5 py-1 text-[10px] font-semibold text-white/35">Live</span>
          </div>
          <div className="relative overflow-hidden rounded-[30px] border border-white/10 bg-[#f5f5f7] p-4 text-zinc-900 shadow-2xl md:mx-auto md:max-w-sm xl:mx-0 xl:max-w-none">
            <div className="absolute inset-x-10 -top-16 h-32 rounded-full bg-indigo-400/25 blur-3xl" />
            <div className="relative min-h-[530px] rounded-[24px] bg-white p-5 shadow-sm">
              <div className="mb-10 flex gap-1.5" aria-hidden="true">
                {value.steps.map((step) => <span key={step.id} className={`h-1 flex-1 rounded-full ${step.id === selectedStep?.id ? 'bg-indigo-500' : 'bg-zinc-100'}`} />)}
              </div>
              {selectedStep ? (
                <div className="flex min-h-[430px] flex-col">
                  <div className="grid h-14 w-14 place-items-center rounded-[20px] bg-zinc-950 text-white shadow-lg">
                    {selectedStep.type === 'rules' ? <ShieldCheck className="h-6 w-6" /> : selectedStep.type === 'channels' ? <Hash className="h-6 w-6" /> : <Sparkles className="h-6 w-6" />}
                  </div>
                  <p className="mt-8 text-[10px] font-bold uppercase tracking-[0.18em] text-indigo-500">{value.title}</p>
                  <h4 className="mt-2 text-2xl font-semibold tracking-[-0.03em] text-zinc-950">{selectedStep.title}</h4>
                  <p className="mt-3 text-sm leading-6 text-zinc-500">{selectedStep.description}</p>
                  <div className="mt-6 space-y-2">
                    {(selectedStep.type === 'single_choice' || selectedStep.type === 'multi_choice') && selectedStep.options.slice(0, 3).map((option, index) => (
                      <div key={option.id} className={`flex items-center gap-3 rounded-2xl border p-3 text-sm ${index === 0 ? 'border-indigo-200 bg-indigo-50' : 'border-zinc-100 bg-zinc-50'}`}>
                        <span className={`h-4 w-4 ${selectedStep.type === 'single_choice' ? 'rounded-full' : 'rounded'} border-2 ${index === 0 ? 'border-indigo-500' : 'border-zinc-300'}`} />
                        {option.label}
                      </div>
                    ))}
                    {selectedStep.type === 'channels' && channels.filter((channel) => selectedStep.channelIds.includes(channel.id)).slice(0, 3).map((channel) => (
                      <div key={channel.id} className="flex items-center gap-2 rounded-2xl bg-zinc-50 p-3 text-sm"><Hash className="h-4 w-4 text-zinc-400" />{channel.name}</div>
                    ))}
                    {selectedStep.type === 'rules' && <div className="rounded-2xl bg-zinc-50 p-4 text-xs leading-5 text-zinc-500">Community guidelines appear here with a clear agreement check.</div>}
                  </div>
                  <button type="button" tabIndex={-1} className="mt-auto flex min-h-12 items-center justify-center gap-2 rounded-full bg-zinc-950 px-5 text-sm font-semibold text-white">
                    Continue <ChevronRight className="h-4 w-4" />
                  </button>
                </div>
              ) : null}
            </div>
          </div>
        </aside>
      </div>
    </div>
  );
};
