  const subscribeToMessages = (channelId: string) => {
    const subscription = supabase
      .channel(`community_channel:${channelId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'community_messages',
          filter: `channel_id=eq.${channelId}`
        },
        async (payload) => {
          const shouldScroll = shouldFollowMessagesRef.current || payload.new.author_id === currentUser?.id;
          // Fetch the full message with user profile
          const { data, error } = await supabase
            .from('community_messages')
            .select(`
              *,
              user:profiles!community_messages_author_id_fkey (
                id,
                full_name,
                avatar_url
              )
            `)
            .eq('id', payload.new.id)
            .single();

          if (!error && data && activeChannelIdRef.current === channelId) {
            setMessages(prev => {
              if (prev.some(m => m.id === data.id)) return prev;
              visibleMessageIdsRef.current.add(data.id);
              return [...prev, data];
            });
            if (shouldScroll) {
              shouldFollowMessagesRef.current = true;
              window.requestAnimationFrame(() => scrollToBottom('smooth'));
            }
            debouncedFetchSmartRooms();
            if (currentUser?.id) {
              void supabase.from('community_read_states').upsert({
                channel_id: channelId,
                user_id: currentUser.id,
                last_read_message_id: data.id,
                last_read_at: new Date().toISOString(),
              }, { onConflict: 'channel_id,user_id' });
            }
          }
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'community_messages',
          filter: `channel_id=eq.${channelId}`
        },
        (payload) => setMessages((current) => current.map((item) => item.id === payload.new.id ? { ...item, ...payload.new } : item))
      )
      .on(
        'postgres_changes',
        {
          event: 'DELETE',
          schema: 'public',
          table: 'community_messages'
        },
        (payload) => {
          visibleMessageIdsRef.current.delete(payload.old.id);
          setMessages((current) => current.filter((item) => item.id !== payload.old.id));
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'community_message_reactions'
        },
        (payload) => {
          const reaction = payload.new as { message_id?: string; user_id?: string; emoji?: string };
          if (!reaction.message_id || !reaction.user_id || !reaction.emoji) return;
          const messageId = reaction.message_id;
          const userId = reaction.user_id;
          const emoji = reaction.emoji;
          setMessageReactions((current) => {
            if (!visibleMessageIdsRef.current.has(messageId)) return current;
            const existing = current[messageId] || [];
            if (existing.some((item) => item.user_id === userId && item.emoji === emoji)) return current;
            return {
              ...current,
              [messageId]: [...existing, { user_id: userId, emoji }],
            };
          });
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'DELETE',
          schema: 'public',
          table: 'community_message_reactions'
        },
        (payload) => {
          const reaction = payload.old as { message_id?: string; user_id?: string; emoji?: string };
          if (!reaction.message_id || !reaction.user_id || !reaction.emoji) return;
          const messageId = reaction.message_id;
          const userId = reaction.user_id;
          const emoji = reaction.emoji;
          setMessageReactions((current) => ({
            ...current,
            [messageId]: (current[messageId] || []).filter(
              (item) => item.user_id !== userId || item.emoji !== emoji,
            ),
          }));
        }
      )
      .subscribe();

    return () => {
      void supabase.removeChannel(subscription);
    };
  };

