  const handleSendMessage = async (
    content: string,
    attachments?: any[],
    audioUrl?: string,
    onUploadProgress?: (progress: { percent: number; transferredBytes: number; totalBytes: number }) => void,
  ): Promise<boolean> => {
    if ((!content.trim() && !audioUrl && (!attachments || attachments.length === 0)) || !activeChannel || !currentUser) return false;

    try {
      let metadata: any = {};

      if (attachments && attachments.length > 0) {
        const file = attachments[0].file as File;
        const safeExtension = file.name.split('.').pop()?.toLowerCase().replace(/[^a-z0-9]/g, '') || 'bin';
        const fileToken = typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : `${Date.now()}`;
        const isCourseVideo = activeChannel.type === 'course' && file.type.startsWith('video/');
        const bucketId = isCourseVideo ? 'course-videos' : 'community-media';
        const contentFolder = activeChannel.type === 'course' ? 'courses' : 'channels';
        const logicalPath = `communities/${communityId}/${contentFolder}/${activeChannel.id}/${fileToken}.${safeExtension}`;
        const storedObject = await uploadWerseeFile({
          bucketId,
          logicalPath,
          file,
          onProgress: onUploadProgress,
        });
        const publicUrl = await resolveWerseeFileUrl(bucketId, storedObject);

        metadata = {
          attachments: [{
            type: file.type.startsWith('image/') ? 'image' : 'video',
            url: publicUrl,
            name: file.name,
            objectId: storedObject.objectId,
            fileId: storedObject.fileId,
            bucketId: storedObject.bucketId,
            logicalPath: storedObject.logicalPath,
            provider: storedObject.provider,
            mimeType: storedObject.mimeType,
            sizeBytes: storedObject.sizeBytes,
          }],
        };
      }

      const newMessage = {
        channel_id: activeChannel.id,
        author_id: currentUser.id,
        content: content.trim(),
        audio_url: audioUrl,
        metadata: Object.keys(metadata).length > 0 ? metadata : undefined,
        parent_message_id: replyingTo?.id || null,
      };

      const { error } = await supabase
        .from('community_messages')
        .insert(newMessage);

      if (error) throw error;

      setReplyingTo(null);
      handleTypingChange(false);
      return true;
    } catch (error) {
      console.error('Error sending community content:', error);
      appToast(activeChannel.type === 'course' ? 'Course content could not be published.' : 'Message could not be sent.');
      return false;
    }
  };

