  const handleContextMenuAction = async (action: string, user: any) => {
    setContextMenu(null);
    setShowMembersModal(false);
    const targetUserId = user.user_id || user.id;
    switch (action) {
      case 'profile':
        navigate(`/profile/${encodeURIComponent(targetUserId)}`);
        break;
      case 'message':
        if (targetUserId === currentUser?.id) {
          appToast('This is your own profile.');
          break;
        }
        try {
          const { data: chatId, error } = await supabase.rpc('get_or_create_direct_chat', {
            p_other_user_id: targetUserId,
          });
          if (error) throw error;
          if (!chatId) throw new Error('No conversation was created.');
          navigate(routes.workspaceChats({ chatId: identifiers.chatId(String(chatId)) }));
        } catch (error) {
          console.error('Error starting direct chat:', error);
          appToast('Conversation could not be opened.');
        }
        break;
      case 'roles':
        setSelectedUser(user);
        setShowManageRolesModal(true);
        break;
      case 'kick':
        setConfirmModal({
          show: true,
          title: 'Kick User',
          message: `Are you sure you want to kick ${user.full_name || user.name || 'this user'}?`,
          onConfirm: async () => {
            const { error } = await supabase
              .from('community_members')
              .delete()
              .eq('community_id', communityId)
              .eq('user_id', targetUserId);
            if (error) {
              appToast('Member could not be removed.');
            } else {
              appToast('Member removed', 'success');
              await fetchMembers();
            }
            setConfirmModal(null);
          }
        });
        break;
      case 'ban':
        setConfirmModal({
          show: true,
          title: 'Ban User',
          message: `Are you sure you want to ban ${user.full_name || user.name || 'this user'}?`,
          onConfirm: async () => {
            const { error: banError } = await supabase
              .from('community_bans')
              .insert({
                community_id: communityId,
                user_id: targetUserId,
                banned_by: currentUser?.id,
              });
            if (!banError) {
              await supabase
                .from('community_members')
                .delete()
                .eq('community_id', communityId)
                .eq('user_id', targetUserId);
              appToast('Member banned', 'success');
              await fetchMembers();
            } else {
              appToast('Member could not be banned.');
            }
            setConfirmModal(null);
          }
        });
        break;
    }
  };

