export interface CommunityLandingBenefit {
  title: string;
  description: string;
}

export interface CommunityLandingPageConfig {
  version: 1;
  vibe: 'casual' | 'startup' | 'gaming' | 'creator';
  generated: boolean;
  published: boolean;
  eyebrow: string;
  headline: string;
  subheadline: string;
  primaryCta: string;
  secondaryCta: string;
  benefits: CommunityLandingBenefit[];
  seoTitle: string;
  seoDescription: string;
  accentColor: string;
  generatedAt?: string;
}

const VIBES = new Set<CommunityLandingPageConfig['vibe']>(['casual', 'startup', 'gaming', 'creator']);

const cleanText = (value: unknown, fallback: string, max: number) => {
  if (typeof value !== 'string') return fallback;
  const normalized = value.trim().replace(/\s+/g, ' ');
  return normalized ? normalized.slice(0, max) : fallback;
};

const cleanColor = (value: unknown, fallback: string) => (
  typeof value === 'string' && /^#[0-9a-f]{6}$/i.test(value) ? value : fallback
);

export const normalizeCommunityLandingPage = (
  value: unknown,
  fallback: { name: string; description?: string; vibe?: string; accentColor?: string },
): CommunityLandingPageConfig => {
  const record = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const name = cleanText(fallback.name, 'Your community', 80);
  const description = cleanText(fallback.description, `Join ${name} and meet people who share your interests.`, 240);
  const vibe = VIBES.has(record.vibe as CommunityLandingPageConfig['vibe'])
    ? record.vibe as CommunityLandingPageConfig['vibe']
    : VIBES.has(fallback.vibe as CommunityLandingPageConfig['vibe'])
      ? fallback.vibe as CommunityLandingPageConfig['vibe']
      : 'casual';
  const benefits = (Array.isArray(record.benefits) ? record.benefits : [])
    .map((benefit) => {
      if (!benefit || typeof benefit !== 'object' || Array.isArray(benefit)) return null;
      const item = benefit as Record<string, unknown>;
      const title = cleanText(item.title, '', 70);
      const benefitDescription = cleanText(item.description, '', 180);
      return title && benefitDescription ? { title, description: benefitDescription } : null;
    })
    .filter((benefit): benefit is CommunityLandingBenefit => Boolean(benefit))
    .slice(0, 4);

  return {
    version: 1,
    vibe,
    generated: record.generated === true,
    published: record.published === true,
    eyebrow: cleanText(record.eyebrow, 'A community on Wersee', 60),
    headline: cleanText(record.headline, `Find your people in ${name}.`, 90),
    subheadline: cleanText(record.subheadline, description, 240),
    primaryCta: cleanText(record.primaryCta, 'Join community', 36),
    secondaryCta: cleanText(record.secondaryCta, 'Explore what’s inside', 36),
    benefits: benefits.length >= 3 ? benefits : [
      { title: 'Meet your people', description: 'Connect around shared ideas, goals and interests.' },
      { title: 'Join the conversation', description: 'Discover focused channels without the noise.' },
      { title: 'Grow together', description: 'Share progress, resources and useful feedback.' },
    ],
    seoTitle: cleanText(record.seoTitle, `${name} community | Wersee`, 70),
    seoDescription: cleanText(record.seoDescription, description, 160),
    accentColor: cleanColor(record.accentColor, cleanColor(fallback.accentColor, '#6366f1')),
    ...(typeof record.generatedAt === 'string' ? { generatedAt: record.generatedAt } : {}),
  };
};

const extractJsonObject = (value: string) => {
  const withoutFence = value.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  const start = withoutFence.indexOf('{');
  const end = withoutFence.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('Wersee AI did not return a usable landing page draft.');
  return JSON.parse(withoutFence.slice(start, end + 1)) as unknown;
};

export const parseCommunityLandingDraft = (
  aiText: string,
  fallback: { name: string; description?: string; vibe?: string; accentColor?: string },
) => {
  const parsed = extractJsonObject(aiText);
  const rawRecord = parsed && typeof parsed === 'object' && !Array.isArray(parsed)
    ? parsed as Record<string, unknown>
    : {};
  const usableBenefits = (Array.isArray(rawRecord.benefits) ? rawRecord.benefits : []).filter((benefit) => {
    if (!benefit || typeof benefit !== 'object' || Array.isArray(benefit)) return false;
    const item = benefit as Record<string, unknown>;
    return typeof item.title === 'string' && item.title.trim().length > 0
      && typeof item.description === 'string' && item.description.trim().length > 0;
  });
  if (usableBenefits.length < 3) throw new Error('Wersee AI returned an incomplete landing page draft.');
  const normalized = normalizeCommunityLandingPage({
    ...rawRecord,
    generated: true,
    published: false,
    generatedAt: new Date().toISOString(),
  }, fallback);
  return normalized;
};

export const buildCommunityLandingPrompt = (input: {
  name: string;
  description: string;
  vibe: string;
  accentColor: string;
  channelNames: string[];
}) => `Create concise English copy for a premium Wersee community landing page.

Return only one valid JSON object with exactly these keys:
{"eyebrow":"max 60 chars","headline":"max 90 chars","subheadline":"max 240 chars","primaryCta":"max 36 chars","secondaryCta":"max 36 chars","benefits":[{"title":"max 70 chars","description":"max 180 chars"}],"seoTitle":"max 70 chars","seoDescription":"max 160 chars","accentColor":"#RRGGBB"}

Rules:
- Return 3 or 4 honest benefits grounded only in the supplied community details.
- Do not invent member counts, testimonials, awards, activity, events, pricing, or outcomes.
- The primary CTA should invite the visitor to join.
- Use an Apple-like voice: calm, clear, specific, and free of hype.
- Use the provided accent color unless it is unreadable.

COMMUNITY_NAME: ${input.name}
DESCRIPTION: ${input.description || 'No description provided.'}
VIBE: ${input.vibe}
ACCENT_COLOR: ${input.accentColor}
CHANNELS: ${input.channelNames.length ? input.channelNames.join(', ') : 'No public channel names provided.'}`;
